/* Speculative Score-Draft Starter */

// Global setup
const reverb = new Tone.Reverb({ decay: 4, wet: 0.8 }).toDestination();
const chorus = new Tone.Chorus(4, 2.5, 0.7).toDestination();

// Main Arp (PolySynth to avoid note cuts)
const arpSynth = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'sawtooth' },
  envelope: { attack: 0.01, decay: 0.2, sustain: 0.1, release: 0.4 },
  filter: { type: 'lowpass', frequency: 4500, Q: 1.5 },
  volume: -12
}).connect(reverb);
const arpPattern = new Tone.Sequence((time, note) => {
  arpSynth.triggerAttackRelease(note, '16n', time);
}, ['A3', 'C4', 'E4', 'A4', 'C5', 'A4', 'E4', 'C4'], '16n').start(0);

// Lead Pad
const padSynth = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'fatsawtooth', count: 5, spread: 30 },
  envelope: { attack: 1.5, decay: 0.5, sustain: 0.8, release: 2.0 },
  filter: { frequency: 6000, Q: 2 },
  volume: -10
}).connect(chorus).connect(reverb);
// Trigger with long notes, e.g., padSynth.triggerAttackRelease('E5', '2n');

// Bass Arp
const bassSynth = new Tone.MonoSynth({
  oscillator: { type: 'square' },
  envelope: { attack: 0.02, decay: 0.3, sustain: 0.2, release: 0.3 },
  filterEnvelope: { attack: 0.05, decay: 0.2, sustain: 0.1, baseFrequency: 200, octaves: 2 },
  filter: { frequency: 1500, Q: 2.5 },
  volume: -14
}).toDestination();
bassSynth.drive = 0.3;
const bassPattern = new Tone.Sequence((time, note) => {
  bassSynth.triggerAttackRelease(note, '16n', time);
}, ['A2', 'E3', 'A2', 'C3'], '8n').start(0);

// Set tempo and transport
Tone.Transport.bpm.value = 120;
// Tone.Transport.start();

/* Speculative starter code */
const bassSynth = new Tone.MonoSynth({
  oscillator: { type: 'fatsawtooth', count: 3, spread: 25 },
  envelope: { attack: 0.01, decay: 0.2, sustain: 0.8, release: 0.3 },
  filterEnvelope: { attack: 0.01, decay: 0.1, sustain: 0.5, release: 0.4, baseFrequency: 200, octaves: 3 },
  filter: { type: 'lowpass', Q: 2.5 },
  portamento: 0.02
}).toDestination();

const drive = new Tone.Distortion(0.3).connect(bassSynth.output);
bassSynth.output.connect(drive);

const bassPattern = new Tone.Sequence((time, note) => {
  bassSynth.triggerAttackRelease(note, '8n', time);
}, ['A1', 'A1', 'A1', 'A1', 'G1', 'G1', 'A1', 'A1'], '8n');

